    /**
     * @notice pagination query all validators' operator address and credit contract address
     *
     * @param offset the offset of the query
     * @param limit the limit of the query
     *
     * @return operatorAddrs operator addresses
     * @return creditAddrs credit contract addresses
     * @return totalLength total number of validators
     */
    function getValidators(
        uint256 offset,
        uint256 limit
    ) external view returns (address[] memory operatorAddrs, address[] memory creditAddrs, uint256 totalLength) {
        totalLength = _validatorSet.length();
        if (offset >= totalLength) {
            return (operatorAddrs, creditAddrs, totalLength);
        }

        limit = limit == 0 ? totalLength : limit;
        uint256 count = (totalLength - offset) > limit ? limit : (totalLength - offset);
        operatorAddrs = new address[](count);
        creditAddrs = new address[](count);
        for (uint256 i; i < count; ++i) {
            operatorAddrs[i] = _validatorSet.at(offset + i);
            creditAddrs[i] = _validators[operatorAddrs[i]].creditContract;
        }
    }

    /**
     * @notice get the consensus address of a validator
     *
     * @param operatorAddress the operator address of the validator
     *
     * @return consensusAddress the consensus address of the validator
     */
    function getValidatorConsensusAddress(
        address operatorAddress
    ) external view returns (address consensusAddress) {
        Validator memory valInfo = _validators[operatorAddress];
        consensusAddress = valInfo.consensusAddress;
    }

    /**
     * @notice get the credit contract address of a validator
     *
     * @param operatorAddress the operator address of the validator
     *
     * @return creditContract the credit contract address of the validator
     */
    function getValidatorCreditContract(
        address operatorAddress
    ) external view returns (address creditContract) {
        Validator memory valInfo = _validators[operatorAddress];
        creditContract = valInfo.creditContract;
    }

    /**
     * @notice get the vote address of a validator
     *
     * @param operatorAddress the operator address of the validator
     *
     * @return voteAddress the vote address of the validator
     */
    function getValidatorVoteAddress(
        address operatorAddress
    ) external view returns (bytes memory voteAddress) {
        Validator memory valInfo = _validators[operatorAddress];
        voteAddress = valInfo.voteAddress;
    }

    /**
     * @notice get the basic info of a validator
     *
     * @param operatorAddress the operator address of the validator
     *
     * @return createdTime the creation time of the validator
     * @return jailed whether the validator is jailed
     * @return jailUntil the jail time of the validator
     */
    function getValidatorBasicInfo(
        address operatorAddress
    ) external view returns (uint256 createdTime, bool jailed, uint256 jailUntil) {
        Validator memory valInfo = _validators[operatorAddress];
        createdTime = valInfo.createdTime;
        jailed = valInfo.jailed;
        jailUntil = valInfo.jailUntil;
    }

    /**
     * @param operatorAddress the operator address of the validator
     *
     * @return the description of a validator
     */
    function getValidatorDescription(
        address operatorAddress
    ) external view validatorExist(operatorAddress) returns (Description memory) {
        return _validators[operatorAddress].description;
    }

    /**
     * @param operatorAddress the operator address of the validator
     *
     * @return the commission of a validator
     */
    function getValidatorCommission(
        address operatorAddress
    ) external view validatorExist(operatorAddress) returns (Commission memory) {
        return _validators[operatorAddress].commission;
    }

    /**
     * @param operatorAddress the operator address of the validator
     *
     * @return the agent of a validator
     */
    function getValidatorAgent(
        address operatorAddress
    ) external view validatorExist(operatorAddress) returns (address) {
        return _validators[operatorAddress].agent;
    }

    /**
     * @param operatorAddress the operator address of the validator
     *
     * @return the updateTime of a validator
     */
    function getValidatorUpdateTime(
        address operatorAddress
    ) external view validatorExist(operatorAddress) returns (uint256) {
        return _validators[operatorAddress].updateTime;
    }

    /**
     * @dev this function will be used by Parlia consensus engine.
     *
     * @notice get the election info of a validator
     *
     * @param offset the offset of the query
     * @param limit the limit of the query
     *
     * @return consensusAddrs the consensus addresses of the validators
     * @return votingPowers the voting powers of the validators. The voting power will be 0 if the validator is jailed.
     * @return voteAddrs the vote addresses of the validators
     * @return totalLength the total number of validators
     */
    function getValidatorElectionInfo(
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (
            address[] memory consensusAddrs,
            uint256[] memory votingPowers,
            bytes[] memory voteAddrs,
            uint256 totalLength
        )
    {
        totalLength = _validatorSet.length();
        if (offset >= totalLength) {
            return (consensusAddrs, votingPowers, voteAddrs, totalLength);
        }

        limit = limit == 0 ? totalLength : limit;
        uint256 count = (totalLength - offset) > limit ? limit : (totalLength - offset);
        consensusAddrs = new address[](count);
        votingPowers = new uint256[](count);
        voteAddrs = new bytes[](count);
        for (uint256 i; i < count; ++i) {
            address operatorAddress = _validatorSet.at(offset + i);
            Validator memory valInfo = _validators[operatorAddress];
            consensusAddrs[i] = valInfo.consensusAddress;
            votingPowers[i] = valInfo.jailed ? 0 : IStakeCredit(valInfo.creditContract).totalPooledBNB();
            voteAddrs[i] = valInfo.voteAddress;
        }
    }

    /**
     * @notice Adds multiple new NodeIDs to the validator's registry.
     * @param nodeIDs Array of NodeIDs to be added.
     */
    function addNodeIDs(
        bytes32[] calldata nodeIDs
    ) external whenNotPaused notInBlackList validatorExist(_bep563MsgSender()) {
        maxNodeIDsInitializer();

        if (nodeIDs.length == 0) {
            revert InvalidNodeID();
        }

        address operatorAddress = _bep563MsgSender();
        bytes32[] storage existingNodeIDs = validatorNodeIDs[operatorAddress];
        uint256 currentLength = existingNodeIDs.length;

        if (currentLength + nodeIDs.length > maxNodeIDs) {
            revert ExceedsMaxNodeIDs();
        }

        // Check for duplicates in new NodeIDs
        for (uint256 i = 0; i < nodeIDs.length; i++) {
            if (nodeIDs[i] == bytes32(0)) {
                revert InvalidNodeID();
            }
            for (uint256 j = i + 1; j < nodeIDs.length; j++) {
                if (nodeIDs[i] == nodeIDs[j]) {
                    revert DuplicateNodeID();
                }
            }
        }

        // Check for duplicates in existing NodeIDs
        for (uint256 i = 0; i < nodeIDs.length; i++) {
            for (uint256 j = 0; j < currentLength; j++) {
                if (nodeIDs[i] == existingNodeIDs[j]) {
                    revert DuplicateNodeID();
                }
            }
        }

        // Add new NodeIDs
        for (uint256 i = 0; i < nodeIDs.length; i++) {
            existingNodeIDs.push(nodeIDs[i]);
            emit NodeIDAdded(operatorAddress, nodeIDs[i]);
        }
    }

    /**
     * @notice Removes multiple NodeIDs from the validator's registry.
     * @param targetNodeIDs Array of NodeIDs to be removed.
     */
    function removeNodeIDs(
        bytes32[] calldata targetNodeIDs
    ) external whenNotPaused notInBlackList validatorExist(_bep563MsgSender()) {
        address validator = _bep563MsgSender();
        bytes32[] storage nodeIDs = validatorNodeIDs[validator];
        uint256 length = nodeIDs.length;

        // If targetNodeIDs is empty, remove all NodeIDs
        if (targetNodeIDs.length == 0) {
            for (uint256 i = 0; i < length; i++) {
                emit NodeIDRemoved(validator, nodeIDs[i]);
            }
            delete validatorNodeIDs[validator];
            return;
        }

        // Otherwise, remove specific NodeIDs
        for (uint256 i = 0; i < targetNodeIDs.length; i++) {
            bytes32 nodeID = targetNodeIDs[i];
            for (uint256 j = 0; j < length; j++) {
                if (nodeIDs[j] == nodeID) {
                    // Swap and pop
                    nodeIDs[j] = nodeIDs[length - 1];
                    nodeIDs.pop();
                    length--;
                    emit NodeIDRemoved(validator, nodeID);
                    break;
                }
            }
        }

        // Clean up storage if no NodeIDs left
        if (nodeIDs.length == 0) {
            delete validatorNodeIDs[validator];
        }
    }

    /**
     * @notice Returns all validators with their consensus addresses and registered NodeIDs.
     * @param validatorsToQuery The operator addresses of the validators.
     * @return consensusAddresses Array of consensus addresses corresponding to the validators.
     * @return nodeIDsList Array of NodeIDs for each validator.
     */
    function getNodeIDs(
        address[] calldata validatorsToQuery
    ) external view returns (address[] memory consensusAddresses, bytes32[][] memory nodeIDsList) {
        uint256 len = validatorsToQuery.length;
        consensusAddresses = new address[](len);
        nodeIDsList = new bytes32[][](len);

        for (uint256 i = 0; i < len; i++) {
            address operator = validatorsToQuery[i];
            Validator memory valInfo = _validators[operator];
            consensusAddresses[i] = valInfo.consensusAddress;
            nodeIDsList[i] = validatorNodeIDs[operator];
        }

        return (consensusAddresses, nodeIDsList);
    }

    /*----------------- internal functions -----------------*/
    function _checkMoniker(
        string memory moniker
    ) internal pure returns (bool) {
        bytes memory bz = bytes(moniker);

        // 1. moniker length should be between 3 and 9
        if (bz.length < 3 || bz.length > 9) {
            return false;
        }

        // 2. first character should be uppercase
        if (uint8(bz[0]) < 65 || uint8(bz[0]) > 90) {
            return false;
        }

        // 3. only alphanumeric characters are allowed
        for (uint256 i = 1; i < bz.length; ++i) {
            // Check if the ASCII value of the character falls outside the range of alphanumeric characters
            if (
                (uint8(bz[i]) < 48 || uint8(bz[i]) > 57) && (uint8(bz[i]) < 65 || uint8(bz[i]) > 90)
                    && (uint8(bz[i]) < 97 || uint8(bz[i]) > 122)
            ) {
                // Character is a special character
                return false;
            }
        }

        // No special characters found
        return true;
    }

    function _checkVoteAddress(
        address operatorAddress,
        bytes calldata voteAddress,
        bytes calldata blsProof
    ) internal view returns (bool) {
        if (voteAddress.length != BLS_PUBKEY_LENGTH || blsProof.length != BLS_SIG_LENGTH) {
            return false;
        }

        // get msg hash
        bytes32 msgHash = keccak256(abi.encodePacked(operatorAddress, voteAddress, block.chainid));
        bytes memory msgBz = new bytes(32);
        assembly {
            mstore(add(msgBz, 32), msgHash)
        }

        // call the precompiled contract to verify the BLS signature
        // the precompiled contract's address is 0x66
        bytes memory input = bytes.concat(msgBz, blsProof, voteAddress); // length: 32 + 96 + 48 = 176
        bytes memory output = new bytes(1);
        assembly {
            let len := mload(input)
            if iszero(staticcall(not(0), 0x66, add(input, 0x20), len, add(output, 0x20), 0x01)) { revert(0, 0) }
        }
        uint8 result = uint8(output[0]);
        if (result != uint8(1)) {
            return false;
        }
        return true;
    }

    function _deployStakeCredit(address operatorAddress, string memory moniker) internal returns (address) {
        address creditProxy = address(new TransparentUpgradeableProxy(STAKE_CREDIT_ADDR, DEAD_ADDRESS, ""));
        IStakeCredit(creditProxy).initialize{ value: msg.value }(operatorAddress, moniker);
        emit StakeCreditInitialized(operatorAddress, creditProxy);

        return creditProxy;
    }

    function _checkValidatorSelfDelegation(
        address operatorAddress
    ) internal {
        Validator storage valInfo = _validators[operatorAddress];
        if (valInfo.jailed) {
            return;
        }
        if (IStakeCredit(valInfo.creditContract).getPooledBNB(operatorAddress) < minSelfDelegationBNB) {
            _jailValidator(valInfo, block.timestamp + downtimeJailTime);
            IBSCValidatorSet(VALIDATOR_CONTRACT_ADDR).felony(valInfo.consensusAddress);
        }
    }

    function _checkFelonyRecord(address operatorAddress, SlashType slashType) internal returns (bool, uint256) {
        bytes32 slashKey = keccak256(abi.encodePacked(operatorAddress, slashType));
        uint256 jailUntil = _felonyRecords[slashKey];
        // for double sign and malicious vote slash
        // if the validator is already jailed, no need to slash again
        if (jailUntil > block.timestamp) {
            return (false, 0);
        }
        jailUntil = block.timestamp + felonyJailTime;
        _felonyRecords[slashKey] = jailUntil;
        return (true, jailUntil);
    }

    function _jailValidator(Validator storage valInfo, uint256 jailUntil) internal {
        // keep the last eligible validator
        bool isLast = (numOfJailed >= _validatorSet.length() - 1);
        if (isLast) {
            // If staking channel is closed, then BC-fusion is finished and we should keep the last eligible validator here
            emit ValidatorEmptyJailed(valInfo.operatorAddress);
            return;
        }

        if (jailUntil > valInfo.jailUntil) {
            valInfo.jailUntil = jailUntil;
        }

        if (!valInfo.jailed) {
            valInfo.jailed = true;
            numOfJailed += 1;

            emit ValidatorJailed(valInfo.operatorAddress);
        }
    }

    function _claim(address operatorAddress, uint256 requestNumber) internal validatorExist(operatorAddress) {
        uint256 bnbAmount = IStakeCredit(_validators[operatorAddress].creditContract).claim(msg.sender, requestNumber);
        emit Claimed(operatorAddress, msg.sender, bnbAmount);
    }

    function _bep410MsgSender() internal view returns (address) {
        if (agentToOperator[msg.sender] != address(0)) {
            return agentToOperator[msg.sender];
        }

        return msg.sender;
    }

    function _bep563MsgSender() internal view returns (address) {
        if (consensusToOperator[msg.sender] != address(0)) {
            return consensusToOperator[msg.sender];
        }

        return _bep410MsgSender();
    }

    function maxNodeIDsInitializer() internal {
        if (maxNodeIDs == 0) {
            maxNodeIDs = INIT_MAX_NUMBER_NODE_ID;
        }
    }

    function uint2str(uint256 _i) internal pure returns (string memory) {
        if (_i == 0) {
            return "0";
        }
        uint256 j = _i;
        uint256 len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory bstr = new bytes(len);
        uint256 k = len;
        while (_i != 0) {
            k = k - 1;
            uint8 temp = (48 + uint8(_i - _i / 10 * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }
}

contracts/SystemV2.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.17;

contract SystemV2 {
    /*----------------- constants -----------------*/
    address internal constant VALIDATOR_CONTRACT_ADDR = 0x0000000000000000000000000000000000001000;
    address internal constant SLASH_CONTRACT_ADDR = 0x0000000000000000000000000000000000001001;
    address internal constant SYSTEM_REWARD_ADDR = 0x0000000000000000000000000000000000001002;
    address internal constant LIGHT_CLIENT_ADDR = 0x0000000000000000000000000000000000001003;
    address internal constant TOKEN_HUB_ADDR = 0x0000000000000000000000000000000000001004;
    address internal constant INCENTIVIZE_ADDR = 0x0000000000000000000000000000000000001005;
    address internal constant RELAYERHUB_CONTRACT_ADDR = 0x0000000000000000000000000000000000001006;
    address internal constant GOV_HUB_ADDR = 0x0000000000000000000000000000000000001007;
    address internal constant TOKEN_MANAGER_ADDR = 0x0000000000000000000000000000000000001008;
    address internal constant CROSS_CHAIN_CONTRACT_ADDR = 0x0000000000000000000000000000000000002000;
    address internal constant STAKING_CONTRACT_ADDR = 0x0000000000000000000000000000000000002001;
    address internal constant STAKE_HUB_ADDR = 0x0000000000000000000000000000000000002002;
    address internal constant STAKE_CREDIT_ADDR = 0x0000000000000000000000000000000000002003;
    address internal constant GOVERNOR_ADDR = 0x0000000000000000000000000000000000002004;
    address internal constant GOV_TOKEN_ADDR = 0x0000000000000000000000000000000000002005;
    address internal constant TIMELOCK_ADDR = 0x0000000000000000000000000000000000002006;
    address internal constant TOKEN_RECOVER_PORTAL_ADDR = 0x0000000000000000000000000000000000003000;

    /*----------------- errors -----------------*/
    // @notice signature: 0x97b88354
    error UnknownParam(string key, bytes value);
    // @notice signature: 0x0a5a6041
    error InvalidValue(string key, bytes value);
    // @notice signature: 0x116c64a8
    error OnlyCoinbase();
    // @notice signature: 0x83f1b1d3
    error OnlyZeroGasPrice();
    // @notice signature: 0xf22c4390
    error OnlySystemContract(address systemContract);

    /*----------------- events -----------------*/
    event ParamChange(string key, bytes value);

    /*----------------- modifiers -----------------*/
    modifier onlyCoinbase() {
        if (msg.sender != block.coinbase) revert OnlyCoinbase();
        _;
    }

    modifier onlyZeroGasPrice() {
        if (tx.gasprice != 0) revert OnlyZeroGasPrice();
        _;
    }

    modifier onlyCrossChainContract() {
        if (msg.sender != CROSS_CHAIN_CONTRACT_ADDR) revert OnlySystemContract(CROSS_CHAIN_CONTRACT_ADDR);
        _;
    }

    modifier onlyValidatorContract() {
        if (msg.sender != VALIDATOR_CONTRACT_ADDR) revert OnlySystemContract(VALIDATOR_CONTRACT_ADDR);
        _;
    }

    modifier onlySlash() {
        if (msg.sender != SLASH_CONTRACT_ADDR) revert OnlySystemContract(SLASH_CONTRACT_ADDR);
        _;
    }

    modifier onlyGov() {
        if (msg.sender != GOV_HUB_ADDR) revert OnlySystemContract(GOV_HUB_ADDR);
        _;
    }

    modifier onlyGovernor() {
        if (msg.sender != GOVERNOR_ADDR) revert OnlySystemContract(GOVERNOR_ADDR);
        _;
    }

    modifier onlyStakeHub() {
        if (msg.sender != STAKE_HUB_ADDR) revert OnlySystemContract(STAKE_HUB_ADDR);
        _;
    }

    modifier onlyTokenRecoverPortal() {
        require(msg.sender == TOKEN_RECOVER_PORTAL_ADDR, "the msg sender must be token recover portal");
        _;
    }
}

contracts/TokenRecoverPortal.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.17;

import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import "./SystemV2.sol";
import "./extension/Protectable.sol";
import "./interface/0.8.x/ITokenHub.sol";
import "./interface/0.8.x/ITokenRecoverPortal.sol";
import "./lib/0.8.x/Utils.sol";

/**
 * @title TokenRecoverPortal is used to recover the token from BC users.
 * @dev This is designed for the BC users to recover the token from TokenHub.
 * The BC chain will stop and generate a merkle tree root after BC-fusion plan was started.
 * The BC users can recover the token from TokenHub after the merkle tree root is generated.
 * For more details, please refer to the BEP-299(https://github.com/bnb-chain/BEPs/pull/299).
 */
contract TokenRecoverPortal is SystemV2, Initializable, ReentrancyGuardUpgradeable, Protectable {
    using Utils for string;
    using Utils for bytes;

    /*----------------- constants -----------------*/
    // SOURCE_CHAIN_ID is the original chain ID of BC
    // This will be replaced based on the deployment network
    // Mainnet: "Binance-Chain-Tigris"
    // Testnet: "Binance-Chain-Ganges"
    // Rendering script: scripts/generate.py:238
    string public constant SOURCE_CHAIN_ID = "Binance-Chain-Ganges";

    /*----------------- storage -----------------*/
    address public approvalAddress;
    bytes32 public merkleRoot;
    bool public merkleRootAlreadyInit;

    // recoveredMap is used to record the recovered token.
    mapping(bytes32 => bool) private recoveredMap;

    modifier merkelRootReady() {
        if (!merkleRootAlreadyInit) revert MerkleRootNotInitialized();
        if (merkleRoot == bytes32(0)) revert MerkleRootNotInitialized();
        _;
    }

    modifier approvalAddressInit() {
        if (approvalAddress == address(0)) revert ApprovalAddressNotInitialized();
        _;
    }

    /*----------------- errors -----------------*/
    // @notice signature: 0x3e493100
    error AlreadyRecovered();
    // @notice signature: 0x09bde339
    error InvalidProof();
    // @notice signature: 0xad60149e
    error InvalidApprovalSignature();
    // @notice signature: 0x8152ea1b
    error InvalidOwnerPubKeyLength();
    // @notice signature: 0xbc97af2e
    error InvalidOwnerSignatureLength();
    // @notice signature: 0xf36660de
    error MerkleRootAlreadyInitiated();
    // @notice signature: 0xcf1ec32e
    error MerkleRootNotInitialized();
    // @notice signature: 0xc629ac81
    error TokenRecoverPortalPaused();
    // @notice signature: 0xd0dcbbd8
    error ApprovalAddressNotInitialized();

    /*----------------- events -----------------*/
    // This event is triggered whenever a call to #recover succeeds.
    event TokenRecoverRequested(bytes ownerAddress, bytes32 tokenSymbol, address account, uint256 amount);

    /*----------------- init -----------------*/
    function initialize() external initializer onlyCoinbase onlyZeroGasPrice {
        __ReentrancyGuard_init_unchained();

        // Different address will be set depending on the environment
        __Protectable_init_unchained(0x08E68Ec70FA3b629784fDB28887e206ce8561E08);
    }

    /**
     * isRecovered check if the token is recovered.
     * @param node the leaf node of merkle tree.
     * @return the result of check.
     */
    function isRecovered(
        bytes32 node
    ) public view returns (bool) {
        return recoveredMap[node];
    }

    /**
     * For the Beacon Chain account whose funds are not transferred to BSC before BC fusion,
     * can still invoke this function to recover funds on the BSC network.
     * @dev The token will be locked in TokenHub after the signature and the merkel proof is verified.
     * @notice The token will be unlocked after 7 days.
     * @param tokenSymbol is the symbol of token.
     * @param amount is the amount of token.
     * @param ownerPubKey is the secp256k1 public key of the token owner on BC.
     * @param ownerSignature is the secp256k1 signature of the token owner on BC.
     * @param approvalSignature is the eth_secp256k1 signature of the approval.
     * @param merkleProof is the merkle proof of the token owner on BC.
     */
    function recover(
        bytes32 tokenSymbol,
        uint256 amount,
        bytes calldata ownerPubKey,
        bytes calldata ownerSignature,
        bytes calldata approvalSignature,
        bytes32[] calldata merkleProof
    ) external merkelRootReady approvalAddressInit whenNotPaused nonReentrant {
        // Recover the owner address and check signature.
        bytes memory ownerAddr =
            _verifySecp256k1Sig(ownerPubKey, ownerSignature, _tmSignatureHash(tokenSymbol, amount, msg.sender));
        // Generate the leaf node of merkle tree.
        bytes32 node = keccak256(abi.encodePacked(ownerAddr, tokenSymbol, amount));

        // Check if the token is recovered.
        if (isRecovered(node)) revert AlreadyRecovered();

        // Verify the approval signature.
        _verifyApprovalSig(msg.sender, ownerSignature, approvalSignature, node, merkleProof);

        // Verify the merkle proof.
        if (!MerkleProof.verify(merkleProof, merkleRoot, node)) revert InvalidProof();

        // Mark it recovered.
        recoveredMap[node] = true;

        // recover the token from TokenHub contract. it will be unlocked after 7 days.
        ITokenHub(TOKEN_HUB_ADDR).recoverBCAsset(tokenSymbol, msg.sender, amount);

        emit TokenRecoverRequested(ownerAddr, tokenSymbol, msg.sender, amount);
    }

    /**
     * verifyApprovalSig is used to verify the approval signature.
     * @dev The signature is generated by the approval address(need to call a token recovery backend service).
     */
    function _verifyApprovalSig(
        address account,
        bytes memory ownerSignature,
        bytes memory approvalSignature,
        bytes32 leafHash,
        bytes32[] memory merkleProof
    ) internal view {
        bytes memory buffer;
        for (uint256 i = 0; i < merkleProof.length; i++) {
            buffer = abi.encodePacked(buffer, merkleProof[i]);
        }
        // Perform the approvalSignature recovery and ensure the recovered signer is the approval account
        bytes32 hash =
            keccak256(abi.encodePacked(SOURCE_CHAIN_ID, account, ownerSignature, leafHash, merkleRoot, buffer));

        if (recover(approvalSignature, hash) != approvalAddress) revert InvalidApprovalSignature();
    }

    function recover(bytes memory sig, bytes32 hash) internal pure returns (address) {
        // Ensure the signature length is correct
        if (sig.length != 65) revert InvalidApprovalSignature();
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }
        if (v < 27) v += 27;
        if (v < 27 || v > 28) revert InvalidApprovalSignature();
        (address signer,) = ECDSA.tryRecover(hash, v, r, s);
        return signer;
    }

    /**
     * verifySecp256k1Sig is used to verify the secp256k1 signature from BC token owner.
     * @dev The signature is generated by the token owner by BC tool.
     */
    function _verifySecp256k1Sig(
        bytes memory pubKey,
        bytes memory signature,
        bytes32 messageHash
    ) internal view returns (bytes memory) {
        // Ensure the public key is valid
        if (pubKey.length != 33) revert InvalidOwnerPubKeyLength();
        // Ensure the signature length is correct
        if (signature.length != 64) revert InvalidOwnerSignatureLength();

        // assemble input data
        bytes memory msgBz = new bytes(32);
        assembly {
            mstore(add(msgBz, 32), messageHash)
        }
        bytes memory input = bytes.concat(pubKey, signature, msgBz);
        bytes memory output = new bytes(20);
        /* solium-disable-next-line */
        assembly {
            // call Secp256k1SignatureRecover precompile contract
            // Contract address: 0x69
            // input:
            // | PubKey | Signature  |  SignatureMsgHash  |
            // | 33 bytes |  64 bytes    |       32 bytes       |
            // output:
            // | recovered address  |
            // | 20 bytes |
            let len := mload(input)
            if iszero(staticcall(not(0), 0x69, add(input, 0x20), len, add(output, 0x20), 20)) { revert(0, 0) }
        }

        // return the recovered address
        return output;
    }

    /**
     * tmSignatureHash is used to generate the hash of the owner signature.
     * @dev The hash is used to verify the signature from BC token owner.
     */
    function _tmSignatureHash(bytes32 tokenSymbol, uint256 amount, address recipient) internal pure returns (bytes32) {
        return sha256(
            abi.encodePacked(
                '{"account_number":"0","chain_id":"',
                SOURCE_CHAIN_ID,
                '","data":null,"memo":"","msgs":[{"amount":"',
                Utils.bytesToHex(abi.encodePacked(amount), false),
                '","recipient":"',
                Utils.bytesToHex(abi.encodePacked(recipient), true),
                '","token_symbol":"',
                Utils.bytesToHex(abi.encodePacked(tokenSymbol), false),
                '"}],"sequence":"0","source":"0"}'
            )
        );
    }

    /**
     * updateParam is used to update the parameters of TokenRecoverPortal.
     * @dev The parameters can only be updated by the governor.
     * @param key is the key of the parameter.
     * @param value is the value of the parameter.
     */
    function updateParam(string calldata key, bytes calldata value) external onlyGov {
        if (key.compareStrings("approvalAddress")) {
            if (value.length != 20) revert InvalidValue(key, value);
            address newApprovalAddress = value.bytesToAddress(20);
            if (newApprovalAddress == address(0)) revert InvalidValue(key, value);
            approvalAddress = newApprovalAddress;
        } else if (key.compareStrings("merkleRoot")) {
            if (merkleRootAlreadyInit) revert MerkleRootAlreadyInitiated();
            if (value.length != 32) revert InvalidValue(key, value);
            bytes32 newMerkleRoot = value.bytesToBytes32(32);
            if (newMerkleRoot == bytes32(0)) revert InvalidValue(key, value);
            merkleRoot = newMerkleRoot;
            merkleRootAlreadyInit = true;
        } else if (key.compareStrings("tokenRecoverPortalProtector")) {
            if (value.length != 20) revert InvalidValue(key, value);
            address newTokenRecoverPortalProtector = value.bytesToAddress(20);
            if (newTokenRecoverPortalProtector == address(0)) revert InvalidValue(key, value);
            _setProtector(newTokenRecoverPortalProtector);
        } else {
            revert UnknownParam(key, value);
        }
        emit ParamChange(key, value);
    }

    /**
     * cancelTokenRecover is used to cancel the recovery request.
     * @dev The token recover request can only be canceled by the assetProtector.
     * @param tokenSymbol is the symbol of token.
     * @param attacker is the address of the attacker.
     */
    function cancelTokenRecover(bytes32 tokenSymbol, address attacker) external onlyProtector {
        ITokenHub(TOKEN_HUB_ADDR).cancelTokenRecoverLock(tokenSymbol, attacker);
    }
}

